u1 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'تحليل الحالات الجوية','إعادة بناء الحالات الجوية وتقييم التوقعات.',1,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u2 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'الظواهر الجوية القريبة من السطح','الضباب والصقيع والتبريد الإشعاعي.',2,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
