u5 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'إنتاج النشرات والتحذيرات التشغيلية','إعداد النشرات وصياغة الرسائل والتحذيرات وفق الإجراءات الرسمية.',5,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('synoptic-case-study-analysis','تحليل الحالات الجوية ودراسة الحالات التاريخية (Case Studies)','منهجية إعادة بناء الحالة الجوية وربط الخرائط والرصد ومخرجات النماذج بالتطور الفعلي.','{"blocks":[{"type":"heading","text":"ما دراسة الحالة الجوية؟"},{"type":"text","text":"دراسة الحالة تحليل منظم لحدث جوي محدد، من الظروف السابقة لتطوره حتى نهايته. هدفها فهم الآليات الجوية وتقييم ما كان متاحاً من معلومات وقت إصدار التوقع، لا الاكتفاء بمعرفة النتيجة بعد وقوعها."},{"type":"heading","text":"تحديد نطاق الدراسة"},{"type":"list","items":["حدد المنطقة والفترة الزمنية والظاهرة المستهدفة.","حدد وقت إصدار التوقع ومهلة التنبؤ محل التقييم.","اجمع مصادر الرصد والنماذج المتاحة في وقت التشغيل.","وثّق مصادر البيانات ووحداتها وأي فجوات في السجلات."]},{"type":"heading","text":"تحليل البيئة السينوبتيكية"},{"type":"text","text":"ابدأ بخرائط الضغط السطحي والجبهات، ثم خرائط الارتفاعات والدوامية والحركة الرأسية في الطبقات العليا. افحص تدفق الرطوبة ودرجة الحرارة والرياح، وابحث عن توافق الأنظمة السطحية والعلوية."},{"type":"heading","text":"التحليل الرأسي"},{"type":"text","text":"استخدم السبرات الجوية أو المقاطع الرأسية لدراسة الاستقرار والرطوبة والقص الحراري والريحي ومستويات التجمد. تساعد المقارنة بين الطبقات على تفسير نوع الهطول والسحب والظواهر المحتملة."},{"type":"heading","text":"دمج الرصد"},{"type":"list","items":["المحطات: الحرارة والضغط والرطوبة والرياح والهطول.","الرادار: بنية الهطول وحركته وتطوره.","الأقمار الصناعية: السحب ودرجات حرارة قممها وأنماطها.","البرق والسبرات وتقارير الظواهر عند توافرها."]},{"type":"heading","text":"مقارنة التوقع بالواقع"},{"type":"text","text":"قارن التوقعات الصادرة في أوقات مختلفة بما رُصد، مع الحفاظ على مهلة كل توقع. ميّز بين خطأ التوقيت وخطأ الموقع وخطأ الشدة وخطأ نوع الظاهرة، ولا تخلط بين المعلومات التي كانت متاحة مسبقاً وما ظهر لاحقاً."},{"type":"heading","text":"بناء تقرير الحالة"},{"type":"list","items":["ملخص تنفيذي للحدث وآثاره الجوية.","تسلسل زمني للظاهرة ومراحل تطورها.","البيئة السينوبتيكية والحرارية والرطوبية.","أهم مخرجات النماذج والرصد.","مقارنة التوقع بالتحقق ومصادر الخطأ.","الدروس المستفادة والتوصيات التشغيلية."]},{"type":"callout","text":"تجنب تحيز الإدراك اللاحق: قيّم قرار التنبؤ بالمعلومات التي كانت متاحة عند إصداره، ثم استخدم الرصد اللاحق للتحقق والتعلم."},{"type":"example","text":"مثال: لدراسة منخفض مطري، أنشئ خطاً زمنياً كل 6 ساعات، واربط تغير الضغط والجبهات وتدفق الرطوبة بصور الرادار والهطول المرصود، ثم قارن ذلك بتوقعات 24 و48 و72 ساعة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"دراسة الحالة الجيدة تجمع التحليل الفيزيائي والرصد والتوقع والتحقق في قصة زمنية موثقة قابلة للمراجعة والتعلم."}]}',250,45,'["بناء تسلسل زمني للحالة الجوية","دمج خرائط الضغط والارتفاع والرياح والرصد","تقييم أداء التوقعات وتوثيق الدروس المستفادة"]','تحليل الحالات الجوية'),
('fog-frost-and-radiation-cooling','التنبؤ بالضباب والصقيع والتبريد الإشعاعي','تحليل شروط تشكل الضباب والصقيع الليلي ومؤشرات التبريد قرب السطح.','{"blocks":[{"type":"heading","text":"الضباب والرؤية"},{"type":"text","text":"الضباب انخفاض في مدى الرؤية الأفقية بسبب قطرات ماء دقيقة قرب سطح الأرض. يتطلب التنبؤ به فحص الرطوبة ودرجة الحرارة والرياح والغطاء السحابي والتضاريس ومصادر الرطوبة."},{"type":"heading","text":"أنواع الضباب"},{"type":"list","items":["ضباب إشعاعي: يرتبط بفقدان السطح الحرارة ليلاً في ظروف مناسبة.","ضباب انتقالي: ينتج عن مرور هواء رطب فوق سطح أبرد.","ضباب تبخر أو بخار: يتكون عند إضافة بخار ماء إلى هواء أبرد.","ضباب جبهوي: يرتبط بعمليات الهطول والاختلاط قرب الجبهات."]},{"type":"heading","text":"التبريد الإشعاعي الليلي"},{"type":"text","text":"يساعد صفاء السماء وضعف الخلط الهوائي وطول الليل على زيادة تبريد السطح. لكن السحب والرياح والرطوبة وخصائص التربة والغطاء النباتي تؤثر في مقدار التبريد وتوزيعه."},{"type":"heading","text":"مؤشرات تشكل الضباب"},{"type":"list","items":["تقارب درجة حرارة الهواء من درجة الندى.","رياح خفيفة تسمح بالتبريد دون خلط قوي، مع مراعاة الموقع.","رطوبة مرتفعة قرب السطح ووجود مصدر رطوبة.","سماء صافية أو قليلة السحب في حالات الضباب الإشعاعي.","تضاريس الأحواض والأودية ومناطق تجمع الهواء البارد."]},{"type":"heading","text":"الصقيع"},{"type":"text","text":"يرتبط الصقيع بتجمد الرطوبة على الأسطح أو انخفاض حرارة الأنسجة النباتية إلى مستويات مؤثرة. لا تكفي حرارة الهواء المقاسة على ارتفاع قياسي وحدها لتحديد حرارة سطح النبات؛ فقد يبرد السطح أكثر من الهواء المحيط."},{"type":"heading","text":"التمييز بين الصقيع والبرد"},{"type":"text","text":"قد تسجل المحطة حرارة هواء فوق الصفر بينما تهبط حرارة سطح مكشوف إلى ما دون الصفر بفعل التبريد الإشعاعي. لذلك راجع ارتفاع الحساس وموقعه وحرارة السطح والغطاء السحابي والرياح."},{"type":"heading","text":"مخرجات النماذج والرصد"},{"type":"text","text":"افحص حرارة السطح والهواء على مستويات قريبة من الأرض والرطوبة والرياح والسحب، وقارنها بمحطات تمثل الأودية والمرتفعات والسهول. بيانات النموذج الشبكية لا تمثل كل الفروق المحلية."},{"type":"callout","text":"التنبؤ بالضباب والصقيع محلي وحساس للموقع. يجب بيان نطاق الثقة وعدم تعميم قراءة محطة واحدة على منطقة واسعة."},{"type":"example","text":"مثال: تشير التوقعات إلى سماء صافية ورياح خفيفة ورطوبة مرتفعة ليلاً. افحص الانخفاض المتوقع في الحرارة وفرقها عن الندى، ثم قارن بمحطات منخفضة ومرتفعة لتقدير تفاوت الضباب واحتمال الصقيع."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يتطلب التنبؤ بالضباب والصقيع فهم التبادل الحراري قرب السطح والخصائص المحلية، مع دمج النموذج والرصد والتحقق الميداني."}]}',260,40,'["تمييز أنواع الضباب وآليات تشكلها","تقييم ظروف التبريد الإشعاعي والصقيع","استخدام الرطوبة والرياح والسحب وحرارة السطح في التوقع"]','الظواهر الجوية القريبة من السطح'),
('snow-hail-and-winter-storms','التنبؤ بالثلوج والبرد والعواصف الشتوية','فهم البنية الحرارية الرأسية وأنواع الهطول المتجمد وتراكم الثلوج والبرد.','{"blocks":[{"type":"heading","text":"لماذا يعد الملف الرأسي أساسياً؟"},{"type":"text","text":"يعتمد نوع الهطول عند السطح على مسار الجسيمات خلال طبقات الغلاف الجوي. لذلك لا تكفي درجة حرارة السطح وحدها؛ يجب فحص درجات الحرارة والرطوبة وعمق الطبقات الدافئة والباردة فوق الموقع."},{"type":"heading","text":"أنواع الهطول الشتوي"},{"type":"list","items":["الثلج: بلورات أو رقائق تبقى متجمدة حتى وصولها إلى السطح.","المطر المتجمد: قطرات سائلة فائقة التبريد تتجمد عند ملامسة الأسطح.","الحبيبات الجليدية: قطرات أو طبقات متجمدة قبل وصولها إلى السطح.","المطر أو الثلج الرطب: يتأثر بعمق الطبقة الدافئة وحرارة الطبقة القريبة من السطح."]},{"type":"heading","text":"مستوى التجمد والطبقة الرطبة"},{"type":"text","text":"افحص مستوى الصفر الحراري والطبقة ذات الحرارة الموجبة فوقه، وعمق الطبقة الباردة القريبة من السطح. كما أن درجة حرارة البصيلة الرطبة تساعد على فهم التبريد التبخري وتحول نوع الهطول."},{"type":"heading","text":"التنبؤ بتراكم الثلوج"},{"type":"text","text":"يتأثر التراكم بمعدل الهطول ومدة استمراره وحرارة السطح والهواء والرياح وكثافة الثلج والانضغاط والانصهار. لا تحول مكافئ الماء السائل إلى عمق ثلج بنسبة ثابتة في جميع الحالات."},{"type":"heading","text":"البرد والعواصف الرعدية"},{"type":"text","text":"يتكون البرد داخل سحب رعدية قوية عندما تسمح التيارات الصاعدة ببقاء الجسيمات الجليدية ونموها. افحص بيئة الحمل وملف التجمد والقص والرطوبة، مع إدراك أن التنبؤ بموقع البرد وحجمه محلي وصعب."},{"type":"heading","text":"مصادر البيانات"},{"type":"list","items":["السبرات والمقاطع الرأسية للحرارة والرطوبة.","خرائط الهطول ونوعه ومكافئ الماء السائل.","الرادار وصور الأقمار الصناعية وتقارير الرصد.","محطات الحرارة والهطول والارتفاعات المختلفة."]},{"type":"heading","text":"عدم اليقين والتأثير المحلي"},{"type":"text","text":"تؤثر فروق الارتفاع والتضاريس والحرارة القريبة من السطح في خط المطر والثلج. قد يتغير نوع الهطول عبر مسافات قصيرة، لذا استخدم نطاقات ارتفاع واحتمالات بدلاً من خط فاصل حاد عند ضعف الثقة."},{"type":"callout","text":"لا تعتمد على خريطة مستوى التجمد وحدها لتحديد نوع الهطول؛ افحص كامل الملف الرأسي والرصد المحلي ودرجة حرارة السطح."},{"type":"example","text":"مثال: يتوقع النموذج هطولاً مع طبقة دافئة فوق طبقة باردة سطحية. افحص سماكة الطبقتين ودرجة حرارة البصيلة الرطبة لتقييم احتمال الثلج الرطب أو الحبيبات الجليدية أو المطر المتجمد."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يتطلب التنبؤ بالهطول الشتوي قراءة رأسية متكاملة وتقييماً للتراكم والتضاريس والحرارة السطحية، مع توضيح عدم اليقين."}]}',270,45,'["تحليل الملف الحراري الرأسي لتحديد نوع الهطول","تمييز الثلج والمطر المتجمد والبرد","تقييم تراكم الثلوج وعدم اليقين في التوقع"]','الهطول المتجمد والطقس الشتوي'),
('strong-winds-and-dust-storms','التنبؤ بالرياح الشديدة والعواصف الغبارية','تحليل تدرج الضغط والخلط والهبوط والتضاريس ومصادر الغبار لتقدير الرياح وتدهور الرؤية.','{"blocks":[{"type":"heading","text":"العوامل الجوية للرياح القوية"},{"type":"text","text":"تتأثر الرياح بتدرج الضغط والقوة الكوريوليسية والاحتكاك والخلط الرأسي والتضاريس. وقد تنتج الهبات القوية عن انتقال زخم الطبقات الأعلى إلى السطح أو عن أنظمة حملية وجبهات وفرق ضغط محلي."},{"type":"heading","text":"قراءة خرائط الرياح"},{"type":"list","items":["افحص سرعة الرياح واتجاهها على ارتفاعات مختلفة.","قارن رياح 10 أمتار برياح الطبقات الأدنى والمتوسطة.","راقب تدرج الضغط ومواقع المنخفضات والمرتفعات والجبهات.","افحص الخلط النهاري والاستقرار والهبوط والتضاريس."]},{"type":"heading","text":"الرياح المتوسطة والهبات"},{"type":"text","text":"سرعة الرياح المتوسطة والهبة القصوى قياسان مختلفان، ويتأثران بفترة المتوسط ومدة الهبة وارتفاع الحساس وطبيعة الموقع. يجب ذكر تعريف القياس عند إصدار توقع أو مقارنة محطات."},{"type":"heading","text":"آليات إثارة الغبار"},{"type":"text","text":"يتطلب الغبار تربة أو رواسب قابلة للتعرية وجفافاً مناسباً ورياحاً قادرة على رفع الجسيمات. تتأثر شدة الغبار برطوبة التربة والغطاء النباتي وحالة السطح ومصدر الرواسب."},{"type":"heading","text":"الغبار المنقول والرؤية"},{"type":"text","text":"قد يصل الغبار إلى منطقة من مصدر بعيد حتى إن لم تكن الرياح السطحية المحلية هي الأقوى. استخدم اتجاهات الرياح في عدة طبقات وصور الأقمار الصناعية ومحطات الرؤية لتتبع النقل وتقدير توقيت الوصول."},{"type":"heading","text":"دمج البيانات"},{"type":"list","items":["محطات الرياح والهبات والرؤية والرطوبة.","النماذج العددية لحقول الرياح والضغط والخلط.","الأقمار الصناعية لمتابعة أعمدة الغبار ومساراتها.","الرصد المحلي لتحديد شدة التأثير على الطرق والمناطق."]},{"type":"heading","text":"التقييم التشغيلي"},{"type":"text","text":"حدد المنطقة والفترة المتوقعة والسرعات أو مدى الرؤية المتوقعين وفق تعريفات الرصد المحلية. افصل بين ثقة توقع الرياح وثقة توقع الغبار، فقد تكون آلياتهما ومصادر عدم اليقين مختلفة."},{"type":"callout","text":"لا تستنتج حدوث عاصفة غبارية من سرعة الرياح وحدها؛ يجب توافر مصدر غبار وظروف سطح مناسبة وقابلية النقل."},{"type":"example","text":"مثال: يتوقع النموذج رياحاً شمالية غربية متزايدة مع مرور جبهة فوق منطقة جافة. راجع رطوبة التربة ومصادر الغبار أعلى اتجاه الرياح وصور الأقمار ومحطات الرؤية قبل تقدير نطاق التأثر."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التنبؤ بالرياح والغبار يجمع ديناميكا الغلاف الجوي بخصائص السطح والنقل الإقليمي، ويحتاج إلى متابعة الرصد وتحديث التوقع."}]}',280,45,'["تحليل العوامل المؤثرة في سرعة وهبات الرياح","تمييز آليات إثارة الغبار ونقله","دمج الرصد والنماذج وصور الأقمار لتقدير الأثر"]','الرياح والظواهر الغبارية'),
('operational-weather-bulletins-and-warnings','إعداد النشرة الجوية التشغيلية وصياغة التحذيرات','تحويل التحليل والرصد والنماذج إلى نشرة واضحة قابلة للاستخدام مع بيان الثقة والأثر.','{"blocks":[{"type":"heading","text":"الغرض من النشرة التشغيلية"},{"type":"text","text":"النشرة التشغيلية تلخص الحالة الراهنة والتطور المتوقع والظواهر المؤثرة ضمن فترة ومناطق محددة. يجب أن تكون دقيقة ومفهومة ومتسقة مع إجراءات الجهة الرسمية المعتمدة."},{"type":"heading","text":"دورة العمل"},{"type":"list","items":["جمع بيانات المحطات والرادار والأقمار والسبرات.","تحليل الحالة السينوبتيكية والظروف المحلية.","مقارنة النماذج وتقييم عدم اليقين.","صياغة السيناريو الأساسي والبدائل المهمة.","مراجعة الاتساق الجغرافي والزمني والوحدات.","اعتماد النشرة وتوثيق وقت الإصدار والتحديث."]},{"type":"heading","text":"بنية النشرة"},{"type":"list","items":["وقت الإصدار وفترة الصلاحية.","ملخص الحالة الجوية الحالية.","التوقع حسب المناطق والفترات الزمنية.","الظواهر المتوقعة وشدتها واحتمالها عند توفره.","درجات الحرارة والرياح والهطول والرؤية حسب الحاجة.","مستوى الثقة ومصادر عدم اليقين.","موعد التحديث ومصدر المعلومات."]},{"type":"heading","text":"صياغة مكانية وزمنية واضحة"},{"type":"text","text":"استخدم أسماء مناطق محددة وفترات زمنية واضحة. تجنب عبارات مثل قريباً أو في بعض المناطق دون تحديد. عند تغير التوقيت بين المناطق، اذكر التسلسل المتوقع بدلاً من تعميم وقت واحد."},{"type":"heading","text":"من التوقع إلى التحذير"},{"type":"text","text":"التحذير رسالة رسمية مرتبطة بمعايير وإجراءات معتمدة لدى الجهة المختصة. ينبغي أن يوضح الظاهرة والمنطقة والفترة ومستوى الخطورة والأثر المتوقع والإرشادات المعتمدة. لا تبتكر مستويات أو عتبات خارج النظام الرسمي."},{"type":"heading","text":"التواصل مع عدم اليقين"},{"type":"text","text":"عندما تختلف النماذج أو تكون الظاهرة محلية، وضح نطاق الاحتمال أو السيناريوهات بلغة مفهومة. لا تعرض مخرجات نموذج واحد كحقيقة مؤكدة، ولا تجعل التحفظ غامضاً بحيث يفقد المستخدم القدرة على فهم الأثر."},{"type":"heading","text":"قائمة مراجعة قبل الإصدار"},{"type":"list","items":["هل وقت الإصدار والصلاحية واضحان؟","هل المناطق والفترات محددة؟","هل الوحدات وتعريفات الرياح والهطول صحيحة؟","هل النشرة متوافقة مع أحدث الرصد والتحليل؟","هل جرى فصل التوقع عن التحذير الرسمي؟","هل ذُكر وقت التحديث والجهة المعتمدة؟"]},{"type":"callout","text":"يجب أن تصدر التحذيرات الرسمية وفق صلاحيات وإجراءات المركز الوطني المختص، مع مراجعة بشرية واعتماد مسؤول قبل النشر."},{"type":"example","text":"مثال صياغة تدريبية: «تزداد فرص هطول أمطار متفاوتة الشدة على المناطق الغربية مساء الثلاثاء، مع احتمال نشاط الرياح أثناء الهطول. تتحدث التوقعات عند ورود بيانات الرصد الجديدة». هذه صياغة تعليمية وليست تحذيراً فعلياً."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"النشرة الجيدة تحول التحليل العلمي إلى رسالة واضحة ومحددة وقابلة للتحديث. أما التحذير فيتطلب معايير رسمية واعتماداً مؤسسياً ومتابعة مستمرة."}]}',290,45,'["تنظيم دورة إعداد النشرة الجوية","صياغة توقع واضح محدد المكان والزمان","تمييز التحذير عن النشرة وبيان الثقة والأثر"]','إنتاج النشرات والتحذيرات التشغيلية')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'تحليل الحالات الجوية' then u1.id when 'الظواهر الجوية القريبة من السطح' then u2.id when 'الهطول المتجمد والطقس الشتوي' then u3.id when 'الرياح والظواهر الغبارية' then u4.id else u5.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'التحليل التطبيقي والتنبؤ التشغيلي',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;